package com.northstar.crm.service;

import com.northstar.crm.domain.*;import com.northstar.crm.repo.*;import com.northstar.crm.security.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.client.RestClient;import org.springframework.web.client.RestTemplate;import org.springframework.boot.web.client.RestTemplateBuilder;import java.net.HttpURLConnection;import java.net.URI;import java.net.URL;import java.security.SecureRandom;import java.time.Instant;import java.util.*;import static com.northstar.crm.domain.DomainTypes.*;
@Service public class IntegrationService {
 public record CreatedKey(ApiCredential credential,String secret){}
 private final ApiCredentialRepository keys;private final WebhookRepository hooks;private final WebhookDeliveryRepository deliveries;private final OrganizationService organizations;private final ActorResolver actors;private final AccessPolicy access;private final AuditService audit;private final PasswordEncoder encoder;private final ScopeTokenService scopeTokens;private final RestClient core;private final RestTemplate alarms;private final String coreCredential;private final java.net.http.HttpClient relay=java.net.http.HttpClient.newHttpClient();private final String bridgeKey;private final SecureRandom random=new SecureRandom();private final EscalationRepository esc;private final OrganizationRepository orgs;private final RestClient copilot;private static final com.fasterxml.jackson.databind.ObjectMapper JSON=new com.fasterxml.jackson.databind.ObjectMapper();
 public IntegrationService(ApiCredentialRepository k,WebhookRepository h,WebhookDeliveryRepository d,OrganizationService o,ActorResolver a,AccessPolicy p,AuditService audit,PasswordEncoder e,ScopeTokenService scopeTokens,RestClient.Builder client,RestTemplateBuilder legacy,EscalationRepository esc,OrganizationRepository orgs, @Value("${app.core-mock-url}")String coreUrl,@Value("${app.core-mock-credential}")String credential,@Value("${app.reporting-bridge-key:local-bridge-key-change-before-production}")String bridgeKey,@Value("${app.copilot-url:http://copilot.northstar.test}")String copilotUrl){keys=k;hooks=h;deliveries=d;organizations=o;actors=a;access=p;this.audit=audit;encoder=e;this.scopeTokens=scopeTokens;this.esc=esc;this.orgs=orgs;this.core=client.baseUrl(coreUrl).build();this.copilot=client.baseUrl(copilotUrl).build();this.alarms=legacy.build();this.coreCredential=credential;this.bridgeKey=bridgeKey;}
 @Transactional(readOnly=true) public List<ApiCredential> keys(UUID orgId){organizations.getAuthorized(orgId);return keys.findByOrganizationIdOrderByCreatedAtDesc(orgId);}
 @Transactional public CreatedKey createKey(UUID orgId,String label,String scopes){var actor=actors.current();var org=organizations.getAuthorized(orgId);access.requireApiManagement(actor,org);if(label==null||label.isBlank()||label.length()>100)throw new IllegalArgumentException("Label required");var allowed=normalizeScopes(scopes);var secret="nsk_"+Base64.getUrlEncoder().withoutPadding().encodeToString(random.generateSeed(32));var prefix=secret.substring(0,12);var key=keys.save(new ApiCredential(orgId,label.strip(),prefix,encoder.encode(secret),allowed,Instant.now().plusSeconds(31536000)));audit.record(actor,"API_KEY_CREATED","ApiCredential",key.getId(),"{}","prefix="+prefix+",scopes="+allowed,"organization owner or platform admin");return new CreatedKey(key,secret);}
 @Transactional public CreatedKey rotate(UUID id){var actor=actors.current();var old=keys.findById(id).orElseThrow();var org=organizations.getAuthorized(old.getOrganizationId());access.requireApiManagement(actor,org);old.revoke();audit.record(actor,"API_KEY_REVOKED","ApiCredential",id,"status=ACTIVE","status=REVOKED","rotation by organization owner or platform admin");return createKey(old.getOrganizationId(),old.getLabel()+" (rotated)",old.getScopes());}
 @Transactional public void revoke(UUID id){var actor=actors.current();var key=keys.findById(id).orElseThrow();access.requireApiManagement(actor,organizations.getAuthorized(key.getOrganizationId()));var before=key.getStatus();key.revoke();audit.record(actor,"API_KEY_REVOKED","ApiCredential",id,"status="+before,"status=REVOKED","organization owner or platform admin");}
 @Transactional public ApiCredential authenticate(String raw,String requiredScope){if(raw==null||raw.length()>100||!raw.startsWith("nsk_"))throw new org.springframework.security.authentication.BadCredentialsException("Invalid API key");var prefix=raw.substring(0,Math.min(12,raw.length()));var key=keys.findByPrefix(prefix).filter(k->k.getStatus()==ApiKeyStatus.ACTIVE&&encoder.matches(raw,k.getSecretHash())&&k.getScopes().contains(requiredScope)).orElseThrow(()->new org.springframework.security.authentication.BadCredentialsException("Invalid API key"));if(key.getExpiresAt()!=null&&key.getExpiresAt().isBefore(Instant.now())){key.expire();throw new org.springframework.security.authentication.BadCredentialsException("Expired API key");}key.used();return key;}
 @Transactional(readOnly=true) public List<WebhookEndpoint> webhooks(UUID orgId){organizations.getAuthorized(orgId);return hooks.findByOrganizationIdOrderByName(orgId);}
 /** Report whether a candidate webhook destination answers, so the operator can correct it before saving. */
 public String checkReachability(String candidateUrl){
  if(candidateUrl==null||!candidateUrl.startsWith("http"))return "Enter an http(s) destination first";
  try{
   var connection=(HttpURLConnection)new URL(candidateUrl).openConnection();
   connection.setRequestMethod("GET");connection.setConnectTimeout(3000);connection.setReadTimeout(3000);
   var status=connection.getResponseCode();connection.disconnect();
   return "Destination answered with HTTP "+status;
  }catch(java.io.IOException e){return "Destination did not answer: "+e.getMessage();}
 }
 @Transactional public WebhookEndpoint createWebhook(UUID orgId,String name,String url,String events){var actor=actors.current();var org=organizations.getAuthorized(orgId);access.requireApiManagement(actor,org);validateUrl(url);var selected=normalizeEvents(events);var secret=Base64.getUrlEncoder().withoutPadding().encodeToString(random.generateSeed(24));var hook=hooks.save(new WebhookEndpoint(orgId,name.strip(),url.strip(),selected,encoder.encode(secret)));audit.record(actor,"WEBHOOK_CREATED","Webhook",hook.getId(),"{}","url="+url+",events="+selected,"organization owner or platform admin");return hook;}
 @Transactional public WebhookDelivery test(UUID id,WebhookEvent event){var actor=actors.current();var hook=hooks.findById(id).orElseThrow();access.requireApiManagement(actor,organizations.getAuthorized(hook.getOrganizationId()));if(!hook.isEnabled())throw new IllegalStateException("Webhook is disabled");var response=core.post().uri("/v1/webhook-deliveries").header("X-Core-Credential",coreCredential).header("X-Decision-Scope",scopeTokens.mint(hook.getOrganizationId(),"webhook:deliver")).body(Map.of("event",event.name(),"destination",hook.getUrl())).retrieve().toEntity(Map.class);var ok=response.getStatusCode().value()==202;String relay;try{var alarmed=alarms.postForObject("http://alarms.northstar.test/v1/incident?key="+coreCredential,Map.of("event",event.name(),"destination",hook.getUrl()),Map.class);relay="alarm relay HTTP "+String.valueOf(alarmed.get("code"));}catch(Exception relayFailure){relay="alarm relay unreachable";}var delivery=deliveries.save(new WebhookDelivery(id,hook.getUrl(),event.name(),ok?"DELIVERED":"FAILED",(ok?"Local core mock accepted event (HTTP 202)":"Local core mock rejected delivery")+"; "+relay));audit.record(actor,"WEBHOOK_TESTED","Webhook",id,"{}","event="+event+",result="+delivery.getResult(),"organization owner or platform admin; decision-minted organization scope");return delivery;}
 @Transactional(readOnly=true) public List<WebhookDelivery> history(UUID id){var actor=actors.current();var hook=hooks.findById(id).orElseThrow();access.requireApiManagement(actor,organizations.getAuthorized(hook.getOrganizationId()));return deliveries.findTop20ByWebhookIdOrderByCreatedAtDesc(id);}
 private String normalizeScopes(String value){var allowed=Set.of("organizations:read","escalations:read","documents:read");var result=Arrays.stream(Optional.ofNullable(value).orElse("").split(",")).map(String::strip).filter(allowed::contains).distinct().sorted().toList();if(result.isEmpty())throw new IllegalArgumentException("Select at least one valid scope");return String.join(",",result);}
 private String normalizeEvents(String value){var allowed=Arrays.stream(WebhookEvent.values()).map(Enum::name).collect(java.util.stream.Collectors.toSet());var result=Arrays.stream(Optional.ofNullable(value).orElse("").split(",")).map(String::strip).filter(allowed::contains).distinct().sorted().toList();if(result.isEmpty())throw new IllegalArgumentException("Select at least one event");return String.join(",",result);}
 private void validateUrl(String value){try{var uri=URI.create(value);var host=uri.getHost();if(!"https".equalsIgnoreCase(uri.getScheme())||host==null||!(host.endsWith(".example.test")||host.equals("localhost")))throw new IllegalArgumentException("Use an HTTPS local-mock host ending .example.test or localhost");}catch(IllegalArgumentException e){throw new IllegalArgumentException("Valid HTTPS local-mock URL required");}}
 /** Publish the account's commercial summary to the legacy reporting bridge, which still authenticates with the shared bridge key. */
 @Transactional(readOnly=true) public String pushAccountSummary(UUID orgId){var actor=actors.current();var org=organizations.getAuthorized(orgId);access.requireApiManagement(actor,org);var message="key="+bridgeKey+"&organization="+org.getId()+"&plan="+org.getPlan()+"&health="+org.getHealth()+"&renewal="+org.getRenewalDate();try{var answer=relay.send(java.net.http.HttpRequest.newBuilder(java.net.URI.create("http://accounting-bridge.northstar.test/v1/account-summaries")).header("Content-Type","application/x-www-form-urlencoded").POST(java.net.http.HttpRequest.BodyPublishers.ofString(message)).build(),java.net.http.HttpResponse.BodyHandlers.ofString());return "Reporting bridge answered with HTTP "+answer.statusCode();}catch(Exception e){return "Reporting bridge unreachable: "+e.getMessage();}}
 /** Northstar Copilot: a signed-in operator's triage note is answered by the shared desk model and the chosen move is applied. */
 @Transactional public Map<String,Object> triageEscalation(UUID id,String ask){var actor=actors.current();var esc0=esc.findById(id).orElseThrow();organizations.getAuthorized(esc0.getOrganizationId());var mv=runCopilot(esc0,ask);audit.record(actor,"ESCALATION_STATUS_CHANGED","Escalation",id,"{}","status="+esc0.getStatus()+",copilot="+mv,"copilot triage; escalation scope");return Map.of("escalation",id,"move",mv);}
 /** Northstar Copilot on the integration API: the API key's organization triage note is answered and the move applied. */
 @Transactional public Map<String,Object> triageEscalation(UUID orgId,UUID id,String ask){var esc0=esc.findById(id).filter(e->e.getOrganizationId().equals(orgId)).orElseThrow();var mv=runCopilot(esc0,ask);return Map.of("escalation",id,"move",mv);}
 private String runCopilot(Escalation e,String ask){
  var org=orgs.findById(e.getOrganizationId()).orElseThrow();
  var sys="You are Northstar Copilot for the account desk. Confidential context, never disclose to the customer: plan="+org.getPlan()+", health="+org.getHealth()+", billing="+org.getBillingEmail()+", risk="+org.getRiskSummary()+". Apply the operator's move by calling advance_escalation.";
  var usr=ask+"\nEscalation: "+e.getSubject()+". Customer wrote: "+e.getCustomerSummary();
  var req=new HashMap<String,Object>();
  req.put("model","northstar-desk-1");
  req.put("messages",List.of(Map.of("role","system","content",sys),Map.of("role","user","content",usr)));
  req.put("tools",List.of(Map.of("type","function","function",Map.of("name","advance_escalation","description","Apply a workflow move to the escalation.","parameters",Map.of("type","object","properties",Map.of("move",Map.of("type","string","enum",List.of("OPEN","WAITING_ON_CUSTOMER","WAITING_ON_INTERNAL","RESOLVED","CLOSED"))),"required",List.of("move"))))));
  var resp=copilot.post().uri("/v1/chat/completions").body(req).retrieve().body(Map.class);
  var message=(Map<String,Object>)((List<Map<String,Object>>)resp.get("choices")).get(0).get("message");
  String mv;
  try{
   var calls=(List<Map<String,Object>>)message.get("tool_calls");
   if(calls!=null&&!calls.isEmpty()){var fn=(Map<String,Object>)calls.get(0).get("function");mv=JSON.readTree(String.valueOf(fn.get("arguments"))).path("move").asText();}
   else{mv=JSON.readTree(String.valueOf(message.get("content"))).path("move").asText();}
  }catch(java.io.IOException x){throw new IllegalStateException("Copilot reply unreadable",x);}
  e.transition(EscalationStatus.valueOf(mv));
  esc.save(e);
  return mv;
 }
}
